import { fromHex } from '@mysten/sui/utils'

/**
 * Compiled bytecode of `move/token_template/sources/token_template.move`.
 *
 * Regenerate when the Move source changes:
 *
 *   cd move/token_template
 *   sui move build
 *   xxd -p -c 100000 build/token_template/bytecode_modules/token_template.mv
 *
 * Paste the single-line hex output below. The hex blob is the source of
 * truth at deploy time — the .move file is only consulted at build time.
 */
const BYTECODE_HEX =
    ''

export function getTokenTemplateBytecode(): Uint8Array {
    return fromHex(BYTECODE_HEX)
}
